class Solution:

	def solve(self, L, R):
		bit_set = {}
		ans = 0
		for i in range(63):
			for j in range(i + 1, 63):
				for k in range(j + 1, 63):
					curr = 0
					curr |= 1 << i
					curr |= 1 << j
					curr |= 1 << k
					if L <= curr <= R:
						ans += 1
		return ans

